async function openHome(){let last;for(let a=0;a<4;a++){try{const r=await page.goto(`${BASE}/?preview_theme_id=${THEME}&sq_customer_v3=${Date.now()}`,{waitUntil:'domcontentloaded',timeout:90000});if(r?.status()===200){await sleep(900);return}last=new Error('HTTP '+r?.status())}catch(e){last=e}await sleep(2000*(a+1))}throw last}
async function homeLink(handle){const ls=page.locator(`#MainContent a[href*="/collections/${handle}"]`);for(let i=0;i<await ls.count();i++)if(await ls.nth(i).isVisible().catch(()=>false))return ls.nth(i);return null}
async function imageState(link){const img=link.locator('img').first();if(!await img.count())return null;await img.scrollIntoViewIfNeeded().catch(()=>{});const h=await img.elementHandle();if(h)await page.waitForFunction(el=>el.complete&&el.naturalWidth>=10,h,{timeout:8000}).catch(()=>{});return img.evaluate(el=>({complete:el.complete,naturalWidth:el.naturalWidth,naturalHeight:el.naturalHeight,alt:el.alt})).catch(()=>null)}
async function waitV3(){let last;for(let a=0;a<3;a++){try{await page.waitForFunction(()=>document.querySelector('#MainContent')?.dataset.sqRefineV3Ready==='true',null,{timeout:45000});await page.waitForSelector('#MainContent .sq-refine-v3-sidebar',{state:'visible',timeout:15000});await sleep(700);return}catch(e){last=e;if(a<2){await page.reload({waitUntil:'domcontentloaded',timeout:90000}).catch(()=>{});await sleep(1800*(a+1))}}}throw last}
async function inspect(){return page.evaluate(()=>{const visible=e=>{if(!e)return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>2&&r.height>2&&s.display!=='none'&&s.visibility!=='hidden'&&s.opacity!=='0'};const m=document.querySelector('#MainContent'),s=m?[...m.querySelectorAll('.sq-refine-v3-sidebar')].find(visible):null,g=m?[...m.querySelectorAll('.sq-refine-v3-results .product-grid')].find(visible):null,c=g?[...g.querySelectorAll(':scope>.product-grid__item')].filter(x=>visible(x)&&x.querySelector('a[href*="/products/"]')):[],rs=c.slice(0,8).map(x=>x.getBoundingClientRect()),row=rs.length?rs.filter(r=>Math.abs(r.y-rs[0].y)<4).length:0,t=s?.querySelector('.sq-refine-v3-sidebar__title'),sr=s?.getBoundingClientRect(),tr=t?.getBoundingClientRect(),legacy=m?[...m.querySelectorAll('[class*="button-tree"],[class*="root-categories"],[class*="third-level"],[class*="branch-grid"],[class*="type-grid"],[class*="program-tree"],[class*="category-grid"],[class*="navigation-grid"],.sqbfl')].filter(e=>visible(e)&&!e.closest('.sq-refine-v3-sidebar,.sq-refine-v3-results')).length:0;return{ready:m?.dataset.sqRefineV3Ready==='true',error:m?.dataset.sqRefineV3Error||'',side:!!s,title:(t?.textContent||'').trim(),headerBg:t?getComputedStyle(t).backgroundColor:'',headerGap:sr&&tr?Math.round(Math.max(0,sr.right-tr.right)*10)/10:null,sidePos:s?getComputedStyle(s).position:'',cards:c.length,row,legacy,normalized:s?.dataset.sqRefineV3TaxonomyNormalized||'',events:(window.__sqCustomerAudit?.events||[]).slice(0,200)}})}
async function filterJourney(root){const old=page.url(),before=await page.evaluate(()=>[...document.querySelectorAll('#MainContent .sq-refine-v3-results .product-grid a[href*="/products/"]')].slice(0,8).map(a=>a.href));const picked=await page.evaluate(()=>{const groups=[...document.querySelectorAll('#MainContent .sq-refine-v3-sidebar details.sq-refine-v3-group')];for(const d of groups){d.open=true;const i=[...d.querySelectorAll('input[type="checkbox"]:not([disabled])')].find(x=>!x.checked);if(i){const label=(i.closest('label')?.querySelector('span')?.textContent||i.value||'').replace(/\s+/g,' ').trim();const meta={label,kind:i.dataset.kind||'',target:i.dataset.target||'',filterName:i.dataset.filterName||'',filterValue:i.dataset.filterValue||''};i.click();return meta}}return null});if(!picked)return{skipped:'no unchecked enabled checkbox'};await page.waitForFunction(u=>location.href!==u,old,{timeout:15000}).catch(()=>{});await waitV3();const afterUrl=page.url(),after=await page.evaluate(()=>[...document.querySelectorAll('#MainContent .sq-refine-v3-results .product-grid a[href*="/products/"]')].slice(0,8).map(a=>a.href));const sideStill=await page.locator('#MainContent .sq-refine-v3-sidebar').isVisible().catch(()=>false);await page.goBack({waitUntil:'domcontentloaded',timeout:90000}).catch(()=>{});await sleep(800);const oneBackUrl=page.url();let backReady=false;if(new URL(oneBackUrl).pathname===`/collections/${root}`){await waitV3().catch(()=>{});backReady=true}return{...picked,oldUrl:old,afterUrl,changed:old!==afterUrl||JSON.stringify(before)!==JSON.stringify(after),sideStill,oneBackUrl,restored:new URL(oneBackUrl).pathname===`/collections/${root}`,backReady}}
const failures=[],results=[];
for(const [name,handle,expect] of subset){const errs=[];let card=null,d=null,filter=null;try{await openHome();const link=await homeLink(handle);if(!link)throw new Error('homepage link missing');const img=await imageState(link),box=await link.boundingBox();card={img,w:Math.round(box?.width||0),h:Math.round(box?.height||0)};if(img&&(!img.complete||img.naturalWidth<10))errs.push('homepage image failed after load wait');await link.click();await page.waitForLoadState('domcontentloaded',{timeout:90000});if(expect)await waitV3();else await sleep(1500);d=await inspect();if(expect){const flashes=d.events.filter(e=>e.type==='legacy-visible'||e.type==='foreign-state-guard-visible');if(!d.ready||d.error||!d.side)errs.push('V3 not ready');if(d.title!=='REFINE PRODUCTS')errs.push('title wrong');if(d.headerBg!=='rgb(8, 40, 63)')errs.push('header navy wrong');if(d.headerGap!==null&&d.headerGap>1.5)errs.push('header seam '+d.headerGap);if(d.legacy||flashes.length)errs.push('legacy/wrong content visible '+JSON.stringify(flashes.slice(0,5)));if(d.cards<1)errs.push('no products');if(mode==='desktop'&&d.cards>=3&&d.row!==3)errs.push('desktop row '+d.row);if(mode==='mobile'&&d.cards>=2&&d.row!==2)errs.push('mobile row '+d.row);if(mode==='desktop'&&d.sidePos!=='sticky')errs.push('desktop sidebar not sticky');if(mode==='mobile'&&d.sidePos==='sticky')errs.push('mobile sidebar sticky');filter=await filterJourney(handle);if(!filter.skipped){if(!filter.changed)errs.push('filter did not change results');if(!filter.sideStill)errs.push('sidebar disappeared after filter');if(!filter.restored)errs.push('single Back did not restore root: '+filter.oneBackUrl)}}else{if(d.side||d.ready||document.documentElement?.dataset?.sqRefineV3ChildIsolation)errs.push('State Guard touched by V3')}}catch(e){errs.push(String(e))}const r={name,handle,mode,card,d,filter,errs};results.push(r);console.log('CUSTOMER_V3_ROUTE '+JSON.stringify(r));if(errs.length)failures.push({name,handle,errs});await page.screenshot({path:`shots/${String(routes.findIndex(r=>r[1]===handle)+1).padStart(2,'0')}-${handle}-${mode}.png`,fullPage:false}).catch(()=>{});await sleep(600)}
await fs.writeFile(`shots/customer-v3-${mode}-${shard}.json`,JSON.stringify({results,failures},null,2));console.log('CUSTOMER_V3_SUMMARY '+JSON.stringify({mode,shard,tested:subset.length,failures}));await browser.close();if(failures.length)process.exit(1);
